def main():
    source = json.loads((DIRECTORY / "app_en.arb").read_text(encoding="utf-8"))
    expected = {key for key in source if not key.startswith("@")}
    placeholders = re.compile(r"\{[A-Za-z][A-Za-z0-9_]*\}")
    for locale, groups in DRAFTS.items():
        translated = {key: source[key] for key in ["english", "hindi", "marathi", "appName", "linkedIn", "devOps"]}
        for group, keys in GROUP_KEYS.items():
            values = groups[group].split("|")
            if len(values) != len(keys):
                raise ValueError(f"{locale}/{group}: expected {len(keys)} strings, got {len(values)}")
            translated.update(zip(keys, values, strict=True))
        translated["shareMessage"] = (
            "🎯 " + translated["shareMessage1"] + " {score}/{totalQuestions} #DevOps Quiz!\n\n"
            "🏆 " + translated["points"] + ": {earnedPoints}\n"
            "🔥 " + translated["bonus"] + ": {bonusPoints}\n"
            "📊 " + translated["percentage"] + ": {percentage}%\n\n"
            + translated["downloadApp"]
        )
        if set(translated) != expected:
            raise ValueError(f"{locale}: mismatched keys: {set(translated) ^ expected}")
        for key, value in translated.items():
            if sorted(placeholders.findall(value)) != sorted(placeholders.findall(source[key])):
                raise ValueError(f"{locale}/{key}: mismatched placeholders")
        metadata = {key: value for key, value in source.items() if key.startswith("@") and key != "@@locale"}
        output = {"@@locale": locale, **translated, **metadata}
        (DIRECTORY / f"app_{locale}.arb").write_text(
            json.dumps(output, ensure_ascii=False, indent=2) + "\n", encoding="utf-8",
        )
        print(f"{locale}: wrote {len(translated)} reviewed-structure draft messages")


if __name__ == "__main__":
    main()